import java.util.ArrayList;

public class Room {
    private int temperature;
    private ArrayList devices;

    public Room(int startingTemperature) {
        this.temperature = startingTemperature;
        this.devices = new ArrayList();
    }

    public ArrayList getDevices() {
        return this.devices;
    }

    public boolean addDevice(Device d) {
        if (this.devices.contains(d)) {
            return false;
        }
        if (d instanceof PortableDevice) {
            this.devices.add(d);
            return true;
        }
        if (d instanceof AC || d instanceof CeilingFan) {
            this.devices.add(d);
            return true;
        }
        return false;
    }

    public boolean removeDevice(Device d) {
        if (d instanceof PortableDevice) {
            return this.devices.remove(d);
        }
        return false;
    }

    public int getTemperatureDrop() {
        int totalDrop = 0;
        for (Device d : this.devices) {
            if (d.isOn()) {
                totalDrop += d.coolsBy();
            }
        }
        return totalDrop;
    }

    public int getTemperature() {
        int totalDrop = this.getTemperatureDrop();
        return this.temperature - totalDrop;
    }

    public int getBreeziness() {
        int totalBreeziness = 0;
        for (Device d : this.devices) {
            if (d.isOn()) {
                totalBreeziness += d.getBreeziness();
            }
        }
        return totalBreeziness;
    }

    public int getNoisiness() {
        int totalNoisiness = 0;
        for (Device d : this.devices) {
            if (d.isOn()) {
                totalNoisiness += d.getNoisiness();
            }
        }
        return totalNoisiness;
    }

    public void printState() {
        System.out.println("Temperature: " + this.getTemperature() + " degrees Celsius");
        System.out.println("Breeziness: " + this.getBreeziness());
        System.out.println("Noisiness: " + this.getNoisiness());
        System.out.println("Devices: ");
        for (Device d : this.devices) {
            String status = d.isOn() ? "On" : "Off";
            System.out.println("- " + d.getID() + " (" + status + ")");
        }
    }
}

